      "content": "{\n  \"name\": \"@linxin666/dsh-client-ui-git-graph\",\n  \"description\": \"External dsh web GUI plugin: a blank-session git branch selector + Git graph, with real host-side git operations and guards, as a dsh profile bundle\",\n  \"version\": \"0.4.8\",\n  \"icon\": \"icon.svg\",\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@11.7.0\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"scripts\": {\n    \"build\": \"tsc -b && tsdown\",\n    \"test\": \"vitest run\",\n    \"typecheck\": \"tsc -b --pretty false\",\n    \"prepare\": \"tsdown --config tsdown.prepare.config.ts\"\n  },\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./src/*\": \"./src/*\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"engines\": {\n      \"dsh\": \">=0.2.1-rc.3\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-api-session-controller\",\n        \"@deepseek-ai/dsh-client-ui-workspace\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"files\": [\n    \"lib/**/*.js\",\n    \"lib/**/*.js.map\",\n    \"lib/**/*.d.ts\",\n    \"lib/**/*.d.ts.map\",\n    \"src\",\n    \"cordis.patch.yml\",\n    \"icon.svg\"\n  ],\n  \"license\": \"Apache-2.0\",\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.5\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh\": \">=0.2.1-rc.3\",\n    \"react\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5\",\n    \"@deepseek-ai/dsh-api-remotes\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-api-workspace-controller\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-connection\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-locale\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-store\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-session\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-workspace\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-settings\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-subprocess\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-tools\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-workspace\": \"^0.2.1-rc.3\",\n    \"@testing-library/dom\": \"^10.4.1\",\n    \"@testing-library/react\": \"^16.1.0\",\n    \"@types/node\": \"^22.20.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"^18.3.5\",\n    \"jsdom\": \"29.1.1\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^6.0.3\",\n    \"vite-tsconfig-paths\": \"^6.1.1\",\n    \"vitest\": \"^4.1.8\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/zhu1090093659/dsh-web.git\"\n  }\n}\n"
